160	    /**
161	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
162	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
163	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
164	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
165	     */
166	    private String nextCustomerCode(String city, String lastName) {
167	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
168	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
169	        int sequence = (int) this.clinicService.findAllOwners().stream()
170	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
171	            .count() + 1;
172	        return String.format("%s-%s-%04d", city3, last3, sequence);
173	    }
