175	    /**
176	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
177	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
178	     * (business-day) registration date of the owner being created, so owners are counted per
179	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
180	     */
181	    private boolean isDailyLimitReached(LocalDate day) {
182	        long count = this.clinicService.findAllOwners().stream()
183	            .filter(existing -> day.equals(existing.getRegistrationDate()))
184	            .count();
185	        return count >= 100;
186	    }
187	
188	    /**
189	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
190	     * more than 80 owners have already been created for the given business day. Counts the owners
191	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
192	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
193	     * warning.
194	     */
195	    private boolean isBulkSignup(LocalDate day) {
196	        long count = this.clinicService.findAllOwners().stream()
197	            .filter(existing -> day.equals(existing.getRegistrationDate()))
198	            .count();
199	        return count > 80;
200	    }
