202	    /**
203	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
204	     * advance it to the following Monday; a weekday is returned unchanged.
205	     */
206	    private LocalDate toBusinessDay(LocalDate date) {
207	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
208	            date = date.plusDays(1);
209	        }
210	        return date;
211	    }
