213	    /**
214	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
215	     * more owners. Cities are compared case-insensitively, matching {@link #nextCustomerCode}.
216	     */
217	    private boolean isCityAtCapacity(String city) {
218	        long count = this.clinicService.findAllOwners().stream()
219	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
220	            .count();
221	        return count >= 50;
222	    }
